ALTER TABLE "User" ADD COLUMN "avatarId" TEXT NOT NULL DEFAULT '';
ALTER TABLE "WorkOrder" ADD COLUMN "boardId" UUID, ADD COLUMN "assignedById" UUID;
UPDATE "WorkOrder" SET "assignedById"="createdBy";
CREATE TABLE "JobBoard" (id UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"teamId" UUID NOT NULL,"clientId" UUID,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',"createdBy" UUID NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX "JobBoard_organizationId_teamId_idx" ON "JobBoard"("organizationId","teamId");
CREATE TABLE "TimeVisit" (id UUID PRIMARY KEY,"organizationId" UUID NOT NULL,"userId" UUID NOT NULL,"workOrderId" UUID NOT NULL,"teamId" UUID,"assignmentRevision" INTEGER NOT NULL,"startedAt" TIMESTAMP(3) NOT NULL,"endedAt" TIMESTAMP(3),"lastOccurredAt" TIMESTAMP(3) NOT NULL,state TEXT NOT NULL,sequence INTEGER NOT NULL);
CREATE INDEX "TimeVisit_organizationId_startedAt_id_idx" ON "TimeVisit"("organizationId","startedAt",id);
CREATE INDEX "TimeVisit_userId_endedAt_idx" ON "TimeVisit"("userId","endedAt");
CREATE UNIQUE INDEX "TimeVisit_one_open_per_user" ON "TimeVisit"("userId") WHERE "endedAt" IS NULL;
CREATE TABLE "TimeEvent" (id UUID PRIMARY KEY,"requestId" UUID NOT NULL,"visitId" UUID NOT NULL,"organizationId" UUID NOT NULL,"userId" UUID NOT NULL,sequence INTEGER NOT NULL,action TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,location JSONB,note TEXT NOT NULL DEFAULT '',"payloadHash" TEXT NOT NULL);
CREATE UNIQUE INDEX "TimeEvent_userId_requestId_key" ON "TimeEvent"("userId","requestId");
CREATE UNIQUE INDEX "TimeEvent_visitId_sequence_key" ON "TimeEvent"("visitId",sequence);
ALTER TABLE "TimeEvent" ADD CONSTRAINT "TimeEvent_visitId_fkey" FOREIGN KEY ("visitId") REFERENCES "TimeVisit"(id);
ALTER TABLE "JobBoard" ADD CONSTRAINT "JobBoard_teamId_fkey" FOREIGN KEY ("teamId") REFERENCES "Team"(id), ADD CONSTRAINT "JobBoard_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"(id);
ALTER TABLE "WorkOrder" ADD CONSTRAINT "WorkOrder_boardId_fkey" FOREIGN KEY ("boardId") REFERENCES "JobBoard"(id), ADD CONSTRAINT "WorkOrder_assignedById_fkey" FOREIGN KEY ("assignedById") REFERENCES "User"(id);
CREATE FUNCTION protect_time_event() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'Time events are immutable'; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "TimeEvent_immutable" BEFORE UPDATE OR DELETE ON "TimeEvent" FOR EACH ROW EXECUTE FUNCTION protect_time_event();
ALTER TABLE "TimeEvent" ADD CONSTRAINT "TimeEvent_action_check" CHECK (action IN ('check_in','break_start','break_end','check_out'));
ALTER TABLE "TimeVisit" ADD CONSTRAINT "TimeVisit_state_check" CHECK (state IN ('working','break','closed'));
